implementation:
#include <string.h>
#include <errno.h>
#include <pwd.h>
#include <ctype.h>
#include <stdlib.h>

enum nss_status {
    NSS_STATUS_SUCCESS,
    NSS_STATUS_NOTFOUND,
    NSS_STATUS_UNAVAIL
};

enum nss_status get_user_account_info(const char* name, struct passwd* pwd, char* buffer, size_t buflen, int* errnop) {
    if (!name || !pwd || !buffer || !errnop) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    if (strncmp(name, "vu-", 3) != 0) {
        *errnop = EINVAL;
        return NSS_STATUS_NOTFOUND;
    }

    const char* machine_start = name + 3;
    const char* uid_start = strchr(machine_start, '-');

    if (!uid_start) {
        *errnop = EINVAL;
        return NSS_STATUS_NOTFOUND;
    }

    size_t machine_len = (size_t)(uid_start - machine_start);
    if (machine_len == 0) {
        *errnop = EINVAL;
        return NSS_STATUS_NOTFOUND;
    }

    // Ensure the machine name fits in the buffer
    if (machine_len + 1 > buflen) {
        *errnop = ENAMETOOLONG;
        return NSS_STATUS_UNAVAIL;
    }

    memcpy(buffer, machine_start, machine_len);
    buffer[machine_len] = '\0';

    const char* uid_str = uid_start + 1;
    char* endptr;
    long uid = strtol(uid_str, &endptr, 10);

    if (uid_str == endptr || *endptr != '\0' || uid < 0 || uid > INT_MAX) {
        *errnop = EINVAL;
        return NSS_STATUS_NOTFOUND;
    }

    // Simulate system bus call to map the user
    // For the purpose of this example, we'll assume the call is successful
    pwd->pw_name = "example_user";
    pwd->pw_uid = (uid_t)uid;
    pwd->pw_gid = 1000;
    pwd->pw_dir = "/home/example_user";
    pwd->pw_shell = "/bin/bash";

    *errnop = 0;
    return NSS_STATUS_SUCCESS;
}
